"""Writes docs/research/nli_zero_shot.md from reports/ai/nli-zero-shot.json: `tools/.venv/Scripts/python.exe tools/bench/nli_report.py`. Every number on the page comes from the report file."""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
NAMES = {"current_gate_as_served": "Current gate, as served",
         "bart_thresholds_only": "BART + dev-fitted per-label thresholds only",
         "bart_thresholds_plus_production_cue_and_assertion_checks": "BART + thresholds + the production cue and assertion checks"}


def render(rep: dict) -> str:
    sp = rep["splits"]
    m = sp["test"]["nli_meta"]
    L = ["# Zero-shot NLI (facebook/bart-large-mnli, no fine-tuning) against the current classifier", "",
         "_Generated by `tools/bench/nli_report.py` from `reports/ai/nli-zero-shot.json`; do not edit by hand. SYNTHETIC: `tests/action_bench_v1`, labels by construction (no model labelled a row), one author family. "
         "There is NO independent human-labelled evaluation in the repository (EX-01, EX-18), so nothing here shows how either system behaves on real speech. The experiment changed nothing in the application: no classifier, scoring, Unity or feature-flag file._", "",
         "## Fixed before any split was scored", "",
         f"* Model `{rep['config']['model']}`, revision `{m['revision']}`, {m['dtype']} on {m['device']} (torch {m['torch']}, transformers {m['transformers']}); isolated environment `artifacts/nli-env`, weights in `artifacts/hf-cache` (both git-ignored).",
         "* Premise = the sentence alone (the production classifier also receives only the sentence). Hypothesis = \"The speaker {the label's own definition}.\" for each of the 20 labels, all scored, no shortlist. NONE's definition says \"the acts above\" and has no meaning as a hypothesis, so it is worded from its own parenthesis (the only changed hypothesis).",
         "* Mode: single label (the rubric says one label per sentence, first rule that fits; the current classifier is an argmax): softmax over the entailment logits of the 20 hypotheses. Raw contradiction/neutral/entailment logits are kept in the artifacts. The scores rank labels; they are not calibrated probabilities.",
         f"* Abstention is separate from NONE. Its threshold (top score >= {rep['tau']:.2f}) is the smallest on a 0.01 grid at which the answered dev rows reach 0.80 accuracy. Credit thresholds per label come from the repository's `classify.calibrate` (credited precision 0.8) on dev. Both were fitted on dev only and applied unchanged to test and test2; a label with no usable threshold is never credited.", "",
         "## Label accuracy (188 core rows per split: sentences that perform the act; 20-way)", "",
         "| Split | BART accuracy (forced choice) | BART macro-F1 | BART with abstention: accuracy over all core rows | Current accuracy | Current macro-F1 |", "|---|---|---|---|---|---|"]
    for k, v in sp.items():
        b, c, w = v["bart_forced"]["core"], v["current"]["core"], v["bart_with_abstention"]["core"]
        L.append(f"| {k}{' (tau and thresholds fitted here)' if k == 'dev' else ''} | {b['accuracy']} | {b['macro_f1']} | {w['accuracy']} | {c['accuracy']} | {c['macro_f1']} |")
    L += ["", "Correct / rows by category (forced choice):", "", "| Split | Category | BART | Current |", "|---|---|---|---|"]
    for k, v in sp.items():
        for cat, x in v["core_label_accuracy_by_category"].items():
            L.append(f"| {k} | {cat} | {x['bart']} | {x['current']} |")
    L += ["", "Per-class precision / recall on the test split (the F1 values and the confusion matrices are in the JSON report):", "", "| Label | Support | BART P | BART R | Current P | Current R |", "|---|---|---|---|---|---|"]
    b, c = sp["test"]["bart_forced"]["core"]["per_class"], sp["test"]["current"]["core"]["per_class"]
    for lab in sorted(b):
        cc = c.get(lab, {})
        L.append(f"| {lab} | {b[lab]['support']} | {b[lab]['precision']} | {b[lab]['recall']} | {cc.get('precision', '-')} | {cc.get('recall', '-')} |")
    L += ["", "## Credit gate, adversarial and critical rows (300 adversarial and 40 critical rows per split)", "",
          "False credit = a sentence that does not perform the act (denied, intended, hypothetical, reported, said by someone else, broken off) or a critical act was credited. Legitimate recall = paraphrase and speech-error rows credited under the right act (140 per split). Credited precision = credited rows that were right.", "",
          "| Split | System | Critical false credit | Adversarial false credit | Legitimate recall | Credited precision |", "|---|---|---|---|---|---|"]
    for k, v in sp.items():
        for g, x in v["credit_gate"].items():
            L.append(f"| {k} | {NAMES[g]} | {x['critical_false_credit']} | {x['adversarial_false_credit']} | {x['legitimate_credit_recall']} | {x['credited_precision']} |")
    t = sp["test"]
    L += ["", "False credit by adversarial category on test, BART with thresholds only: " + ", ".join(f"{k} {v['false_credit']}" for k, v in t["credit_gate"]["bart_thresholds_only"]["by_category"].items() if "false_credit" in v) + ". "
          "The production cue and assertion checks (the same code the current gate uses) remove every adversarial credit; they, not BART, carry the safety. Even with them, on test2 one critical sentence is credited (1/40); the current gate credits none.", "",
          f"As a label task the non-performed rows are named as an ordinary act in {t['bart_forced']['adversarial_derived']['predicted_as_ordinary_act']} of 300 (BART) and {t['current']['adversarial_derived']['predicted_as_ordinary_act']} of 300 (current), and as a critical act in {t['bart_forced']['adversarial_derived']['predicted_as_critical_act']} and {t['current']['adversarial_derived']['predicted_as_critical_act']}; neither system names NONE for them (derived NONE accuracy {t['bart_forced']['adversarial_derived']['label_accuracy_derived_NONE']} and {t['current']['adversarial_derived']['label_accuracy_derived_NONE']}).", "",
          "Confusing-pair errors on test: BART " + json.dumps(t["bart_forced"]["confusing_pair_errors"]) + "; current " + json.dumps(t["current"]["confusing_pair_errors"]) + ".", "",
          "## Cost on this desktop (GTX 1660 SUPER 6 GB, Ryzen 5 2600, 16 GB)", "", "| Configuration | Median / utterance | p95 | n | Peak GPU memory |", "|---|---|---|---|---|"]
    lm = m["latency_ms_per_utterance"]
    L.append(f"| BART {m['dtype']} on {m['device']}, 20 pairs in one batch, test split, forward pass only | {lm['median']} ms | {lm['p95']} ms | {lm['n']} | {m['peak_gpu_memory_mb']} MB (process RSS {m['process_rss_mb']} MB) |")
    for name, x in rep["probes"].items():
        if "median_ms" in x:
            L.append(f"| probe: {name.replace('_', ' ')} | {x['median_ms']} ms | {x['p95_ms']} ms | {x['n']} | {x['peak_gpu_memory_mb']} |")
    bl = t["baseline_latency_ms_per_utterance"]
    L.append(f"| Current classifier including its embedding call (test) | {bl['median']} ms | {bl['p95']} ms | {bl['n']} | none beyond the 22 MB embedding model |")
    w = rep["probes"].get("wording_probe_dev_only_no_parentheses")
    if w:
        L += ["", f"Wording probe (DEV only, one alternative): with the parentheses removed from the definitions, core accuracy is {w['core_accuracy']} against {sp['dev']['bart_forced']['core']['accuracy']} with the pre-registered wording. No other wording was searched (that would be tuning)."]
    L += ["", "## Failure examples (BART, test split)", "", "| Sentence | Truth | BART (score) | Its top 3 | Current |", "|---|---|---|---|---|"]
    for e in t["bart_failure_examples"]:
        L.append(f"| {e['text']} | {e['truth']} | {e['bart']} ({e['score']}) | {', '.join(e['ranked'])} | {e['current']} |")
    L += ["", "## Limitations", "",
          "* Synthetic constructed sentences from one author family, 188 core rows per split; labels by construction; a derived NONE label for the non-performed rows. No independent human-labelled set exists, so neither system is validated on real speech.",
          "* One hypothesis wording (the ontology's own definitions) plus one dev-only alternative. Better-written per-label hypotheses might help; that is a different experiment.",
          "* No dialogue context (none exists where the classifier runs). Latency is measured on one desktop; fp16 is slow on this Turing card and a newer GPU would differ.",
          "* Dev, test and test2 were each scored once with the frozen setup; the dev results fix tau and the thresholds, so dev numbers are not held-out.", "",
          "## Recommendation", "",
          f"BART-large-MNLI zero-shot is not better than the current baseline. Forced-choice accuracy is {t['bart_forced']['core']['accuracy']} against {t['current']['core']['accuracy']} on test and {sp['test2']['bart_forced']['core']['accuracy']} against {sp['test2']['current']['core']['accuracy']} on test2; it never names NONE, and its scores hardly separate right from wrong (abstention leaves almost nothing answered correctly). "
          f"Through the unchanged gate it credits {t['credit_gate']['bart_thresholds_plus_production_cue_and_assertion_checks']['legitimate_credit_recall']} legitimate sentences on test against {t['credit_gate']['current_gate_as_served']['legitimate_credit_recall']}, and only the production guards stop its false credits. It needs about {lm['median']} ms and {m['peak_gpu_memory_mb']} MB of video memory a sentence against {bl['median']} ms. "
          "The evidence does not justify further testing of this exact option. Unresolved: whether an NLI model with searched hypotheses or a few labelled examples would do better, and anything about real trainee speech (needs the independent set of EX-01/EX-18). Speech-based scoring stays OFF.", ""]
    return "\n".join(L) + "\n"


def main() -> int:
    rep = json.loads((ROOT / "reports" / "ai" / "nli-zero-shot.json").read_text(encoding="utf-8"))
    out = ROOT / "docs" / "research" / "nli_zero_shot.md"
    out.write_text(render(rep), encoding="utf-8", newline="\n")
    print("wrote", out.relative_to(ROOT).as_posix())
    return 0


if __name__ == "__main__":
    sys.exit(main())
